@@ -30,3 +40,29 @@ export function t(key, lang = "en", params = {}) {

 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** The best supported language for an Accept-Language header (by q-value), else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (Array.isArray(header)) header = header.join(",");
+  if (typeof header !== "string" || header.trim() === "") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [rawTag, ...rawParams] = part.split(";");
+    const tag = rawTag.trim().toLowerCase();
+    if (!tag) continue;
+    let q = 1;
+    for (const p of rawParams) {
+      const [k, v] = p.split("=").map((x) => x.trim().toLowerCase());
+      if (k === "q") q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(v ?? "") ? Number(v) : -1;
+    }
+    if (q <= 0) continue;
+    const lang = tag === "*" ? fallback : tag.split("-")[0];
+    if (!(lang in MESSAGES)) continue;
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
